#include<stdio.h>
int main
{
    int a,b;
    printf("enter 1st no.");
    scanf("%d" ,&a);
    printf("enter 2nd no.");
    scanf("%d" ,&b);
    printf("The subtraction of given 2 no. is %d\n" ,a-b);
    printf("The addition of given 2 no. is %d\n" ,a+b);
    printf("The division of given 2 no. is %d\n" ,a/b);
    printf("The multipication of 2 no. is %d\n" ,a*b);
    return 0;

}
